    "artistId": "greuze",
    "artist": "Greuze Jean-Baptiste",
    "artistSort": "Greuze Jean-Baptiste",
    "title": "Portrait de Michel-Nicolas Hussard",
    "date": "1805",
    "dateDisplay": "vers 1805",
    "century": "XIXe siècle",
    "centuryDisplay": "XIXe s. (vers 1805)",
    "centuryNumeric": 1805,
    "medium": "Peinture à l'huile sur toile",
    "dimensions": "72,5 × 58,8 cm",
    "location": "Musée d'Arts de Nantes",
    "image": "https://lh3.googleusercontent.com/pw/AP1GczNktXs7n1tAe5tShlQJb2KL59yLpmAPaEC-WoGLP5Bvc9pl28R22h0bdK7S4Ciqzz_UrWI3Vsmpxabho2p1wBp3cSaJh7331Pf8piPJJYf1UOzDNZ6hIvwcoHbTn9OHaUrA8UsZH7mmdB6RyTz93LrLrQ=w1681-h2048-s-no-gm?authuser=0",
    "civilization": "France",
